\section{Introduction}

\subsection{Two sequences and one unit}

Let $\delta = 1+\sqrt2$, the \emph{silver ratio}: the fundamental unit of the real quadratic order $\Z[\sqrt2]$. Its powers have integral coordinates,
\begin{equation}\label{eq:spine}
(1+\sqrt2)^n = Q_n + P_n\sqrt2 \qquad (n \ge 0),
\end{equation}
and the two coordinate sequences are
\[
P: \ 0,\,1,\,2,\,5,\,12,\,29,\,70,\,169,\,408,\,985,\,2378,\,5741,\dots
\]
\[
Q: \ 1,\,1,\,3,\,7,\,17,\,41,\,99,\,239,\,577,\,1393,\,3363,\,8119,\dots
\]
Both satisfy the same linear recursion,
\begin{equation}\label{eq:rec}
P_0=0,\ P_1=1,\qquad Q_0=1,\ Q_1=1,\qquad x_{n+2}=2x_{n+1}+x_n.
\end{equation}
$P$ consists of the \emph{Pell numbers} and $Q$ of the \emph{half-companion Pell numbers}. We call the interleaved pair $\{(Q_n,P_n)\}_{n\ge0}$ the \textbf{Pell spine}: it is the norm-one part of the unit group of $\Z[\sqrt2]$, written in coordinates.

\subsection{Methodology: falsification first}

The results below were obtained under a single organising principle: \emph{state every conjecture so that one explicit counterexample suffices to kill it, then attack it.} This forces precision, and, more usefully, makes each death informative: the counterexample points at the missing hypothesis, and the repaired statement is usually the real theorem. Every refutation below is followed by its repair. Seven conjectures fall; their counterexamples all live inside the first thirty terms of the spine, and four die at the same term.

\section{Core arithmetic of the spine}

Throughout, $P$ and $Q$ are as in \eqref{eq:rec}, and all variables denote non-negative integers unless stated otherwise.

\begin{lemma}[One-step laws]\label{lem:onestep}
For all $n$, $\ P_{n+1} = P_n + Q_n$ and $Q_{n+1} = Q_n + 2P_n$.
\end{lemma}

\begin{proof}[Proof sketch]
Simultaneous induction; the two statements feed each other. At $n=0$ they read $1=0+1$ and $1=1+0$. Assuming both at $n$, the recursion \eqref{eq:rec} gives $P_{n+2}=2P_{n+1}+P_n = P_{n+1} + (P_n+Q_n) + P_n$, and the inductive hypothesis for $Q$ converts the tail into $Q_{n+1}$; symmetrically for $Q$.
\end{proof}

Equivalently, Lemma~\ref{lem:onestep} says that multiplication by $\delta = 1+\sqrt2$ acts on coordinates by $\left(\begin{smallmatrix}1&2\\1&1\end{smallmatrix}\right)$, which is \eqref{eq:spine} read one step at a time.

\begin{theorem}[Addition laws]\label{thm:add}
For all $m,n$,
\begin{equation}\label{eq:add}
P_{m+n} = P_mQ_n + Q_mP_n, \qquad Q_{m+n} = Q_mQ_n + 2P_mP_n .
\end{equation}
\end{theorem}

\begin{proof}[Proof sketch]
These are the two components of $\delta^{m+n} = \delta^m\delta^n$ expanded via \eqref{eq:spine}. Combinatorially, both follow from a single simultaneous two-step induction on $n$ with $m$ fixed, using Lemma~\ref{lem:onestep} for the base steps.
\end{proof}

\begin{corollary}[Doubling]\label{cor:double}
$P_{2n} = 2P_nQ_n$ and $Q_{2n} = Q_n^2 + 2P_n^2$.
\end{corollary}

\begin{theorem}[Pell equation on the spine]\label{thm:norm}
For all $n$,
\begin{equation}\label{eq:norm}
Q_n^2 - 2P_n^2 = (-1)^n .
\end{equation}
\end{theorem}

\begin{proof}[Proof sketch]
Take norms in \eqref{eq:spine}: $N(\delta) = (1+\sqrt2)(1-\sqrt2) = -1$, so $N(\delta^n) = (-1)^n$, and $N(Q_n+P_n\sqrt2) = Q_n^2-2P_n^2$. Directly: by Lemma~\ref{lem:onestep}, $Q_{n+1}^2-2P_{n+1}^2 = (Q_n+2P_n)^2 - 2(P_n+Q_n)^2 = -(Q_n^2-2P_n^2)$.
\end{proof}

The alternating sign in \eqref{eq:norm} is the \emph{hidden variable} of this paper: it reappears as the side of the approximation to $\sqrt2$ (\S\ref{sec:approx}), as the sign of the norm distinguishing the two Pell equations (\S\ref{sec:dioph}), and as the parity grading of the companion divisibility law (\S\ref{sec:companion}).

\begin{corollary}[Coprimality]\label{cor:coprime}
$\gcd(P_n,Q_n)=1$ for every $n$.
\end{corollary}

\begin{proof}
Any common divisor divides $Q_n^2-2P_n^2 = \pm1$.
\end{proof}

\begin{theorem}[Matrix bridge and Cassini]\label{thm:cassini}
Let $M = \left(\begin{smallmatrix}2&1\\1&0\end{smallmatrix}\right)$. Then
\[
M^{\,n+1} = \begin{pmatrix} P_{n+2} & P_{n+1} \\ P_{n+1} & P_n \end{pmatrix},
\qquad\text{and consequently}\qquad
P_{n+2}P_n - P_{n+1}^2 = (-1)^{n+1}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
The matrix identity is an induction on $n$ using \eqref{eq:rec}. Since $\det M = -1$ and determinants are multiplicative, $\det M^{n+1} = (-1)^{n+1}$, which is exactly the displayed identity.
\end{proof}

\section{Strong divisibility, and the first four falsifications}

\begin{definition}
An integer sequence $(a_n)$ is a \emph{strong divisibility sequence} if $\gcd(a_m,a_n) = a_{\gcd(m,n)}$ for all $m,n$.
\end{definition}

\begin{lemma}[Euclidean step]\label{lem:euclid}
For all $m,n$, $\ \gcd(P_{m+n},P_n) = \gcd(P_m,P_n)$.
\end{lemma}

\begin{proof}
By \eqref{eq:add}, $P_{m+n} = P_mQ_n + P_nQ_m$; the second summand is a multiple of $P_n$, so $\gcd(P_{m+n},P_n) = \gcd(P_mQ_n,P_n)$. By Corollary~\ref{cor:coprime}, $Q_n$ is coprime to $P_n$ and may be cancelled, leaving $\gcd(P_m,P_n)$.
\end{proof}

\begin{theorem}[Strong divisibility]\label{thm:sd}
For all $m,n$, $\ \gcd(P_m,P_n) = P_{\gcd(m,n)}$.
\end{theorem}

\begin{proof}[Proof sketch]
Strong induction on $m$. For $m=0$ both sides equal $P_n$. For $m>0$, iterating Lemma~\ref{lem:euclid} gives $\gcd(P_{mq+r},P_m) = \gcd(P_r,P_m)$ for all $q,r$; writing $n = mq+r$ with $r = n \bmod m < m$ reduces the pair $(m,n)$ to $(r,m)$, mirroring the Euclidean algorithm on indices, so the inductive hypothesis applies. The recursion terminates at $\gcd(P_0,P_g) = P_g$ with $g = \gcd(m,n)$.
\end{proof}

\begin{theorem}[Divisibility criterion]\label{thm:dvdiff}
$m \mid n \iff P_m \mid P_n$, with no side conditions.
\end{theorem}

\begin{proof}
If $m \mid n$ then $\gcd(m,n)=m$, so Theorem~\ref{thm:sd} gives $\gcd(P_m,P_n)=P_m$. Conversely if $P_m \mid P_n$ then $P_m = P_{\gcd(m,n)}$; since $P$ is strictly increasing from index $1$, this forces $\gcd(m,n)=m$, the cases $m \in \{0,1\}$ being immediate.
\end{proof}

\begin{corollary}\label{cor:primeindex}
If $P_n$ is prime then $n$ is prime.
\end{corollary}

\begin{proof}
If $d \mid n$ with $1<d<n$ then $P_d \mid P_n$ and $1 < P_d < P_n$.
\end{proof}

Corollary~\ref{cor:primeindex} is a strictly one-way implication, as the next four statements show.

\begin{refutation}[Conjecture A]
\emph{If $n$ is prime then $P_n$ is prime.} \textbf{False}: $n=7$ gives $P_7 = 169 = 13^2$.
\end{refutation}

\begin{refutation}[Conjecture B]
\emph{Every Pell number is squarefree.} \textbf{False}: $P_7 = 13^2$. (The analogous assertion for Fibonacci numbers is a long-standing open problem; on the Pell spine it fails at the seventh term.)
\end{refutation}

\begin{refutation}[Conjecture C]
\emph{No Pell number $P_n$ with $n \ge 2$ is a perfect square.} \textbf{False}: $P_7 = 13^2$. (By Ljunggren's theorem $169$ is in fact the only such value, but one counterexample settles the conjecture as stated.)
\end{refutation}

\begin{refutation}[Conjecture D]
\emph{The companion sequence $Q$ is a strong divisibility sequence.} \textbf{False}: $\gcd(Q_3,Q_6) = \gcd(7,99) = 1$, whereas $Q_{\gcd(3,6)} = Q_3 = 7$.
\end{refutation}

Conjecture D fails maximally: the gcd is not merely smaller than predicted, it is $1$. Section~\ref{sec:companion} identifies the true law. Conjectures A, B, C all die at the same term $P_7 = 169$; so does Conjecture F of \S\ref{sec:dioph} and, at one remove, Conjecture G of \S\ref{sec:rank}. The guarded companion statement that does survive is:

\begin{proposition}\label{prop:oddmult}
$Q_n \mid Q_{(2k+1)n}$ for all $n,k$.
\end{proposition}

\begin{proof}[Proof sketch]
Induction on $k$, using $(2(k+1)+1)n = (2k+1)n + 2n$ together with the addition law $Q_{a+2n} = Q_aQ_{2n} + 2P_aP_{2n}$ and the facts $Q_n \mid Q_{2n}-2P_n^2$ and $Q_n \mid P_{2n} = 2P_nQ_n$ from Corollary~\ref{cor:double}.
\end{proof}

\section{Ranks of apparition}\label{sec:rank}

\begin{theorem}[Apparition theorem]\label{thm:app}
For every $m \ge 1$ there exists $n>0$ with $m \mid P_n$.
\end{theorem}

\begin{proof}
Consider the state map $f:\N \to (\Z/m)^2$, $f(n) = (P_n \bmod m,\ P_{n+1}\bmod m)$. The codomain is finite, so $f$ is not injective: there are $i<j$ with $f(i)=f(j)$.

The recursion is \emph{reversible}: $P_n = P_{n+2}-2P_{n+1}$. Hence if $f(a+1)=f(b+1)$, i.e.\ $P_{a+1}\equiv P_{b+1}$ and $P_{a+2}\equiv P_{b+2}$, then subtracting twice the first congruence from the second gives $P_a \equiv P_b$, so $f(a)=f(b)$.

Write $j = i+t$ with $t>0$. Applying the reversibility step $i$ times to $f(i) = f(i+t)$ slides the coincidence to $f(0)=f(t)$. Comparing first coordinates and using $P_0=0$ yields $m \mid P_t$ with $t>0$.
\end{proof}

The argument needs no primality, no factorisation of $m$, and no characteristic-$p$ algebra: finiteness plus invertibility of the transition matrix modulo $m$ (which holds since $\det M = -1$ is a unit modulo every $m$) is the entire content.

\begin{definition}[Rank of apparition]
For $m \ge 1$ set $\rank(m) = \min\{n>0 : m \mid P_n\}$, well defined by Theorem~\ref{thm:app}; set $\rank(0)=0$ by convention.
\end{definition}

