function PELL_PAIR_MOD(n, m):                     # (P_n, Q_n) mod m, O(log n)
    if m = 1: return (0, 0)
    if n = 0: return (0, 1 mod m)
    (p, q) <- PELL_PAIR_MOD(floor(n/2), m)
    p2 <- 2*p*q mod m
    q2 <- q*q + 2*p*p mod m
    if n is even: return (p2, q2)
    else:         return (p2 + q2 mod m, q2 + 2*p2 mod m)

function RANK_PRIME(p):                           # alpha(p)
    if p = 2: return 2
    s <- +1 if p mod 8 in {1, 7} else -1          # the Legendre symbol (2/p)
    for d in DIVISORS(p - s) in increasing order:
        if first component of PELL_PAIR_MOD(d, p) = 0:
            return d
    error: contradicts the Fermat law

function RANK_PRIME_POWER(p, k):                  # alpha(p^k) by lifting
    r <- RANK_PRIME(p); M <- p
    repeat k - 1 times:
        M <- M * p
        if first component of PELL_PAIR_MOD(r, M) != 0:
            r <- r * p
    return r

function PELL_RANK(m):                            # alpha(m)
    if m = 1: return 1
    r <- 1
    for each prime power p^k exactly dividing m:
        r <- lcm(r, RANK_PRIME_POWER(p, k))
    return r

