"""
Certified computation of the rank of apparition alpha(m) on the Pell spine.

alpha(m) is the least n > 0 with m | P_n, where P is the Pell sequence
P(0)=0, P(1)=1, P(n+2)=2P(n+1)+P(n).  Existence is the Apparition Theorem.

Three layers of speed-up over naive iteration:
  1. multiplicativity   alpha(a*b) = lcm(alpha a, alpha b) for coprime a, b,
     so it suffices to compute alpha on prime powers;
  2. the Fermat law     alpha(p) divides p - (2/p) for odd primes p, so the
     candidate set shrinks from {1,...,p^2} to the divisors of p -+ 1;
  3. fast index arithmetic: P_n mod m in O(log n) multiplications via doubling.
"""

from __future__ import annotations

from math import gcd, lcm
from typing import Dict, List, Tuple


def pell_pair_mod(n: int, m: int) -> Tuple[int, int]:
    """Return (P_n mod m, Q_n mod m) in O(log n) multiplications.

    Uses the doubling identities
        P_{2k}   = 2 P_k Q_k,          Q_{2k}   = Q_k^2 + 2 P_k^2,
        P_{2k+1} = P_{2k} + Q_{2k},    Q_{2k+1} = Q_{2k} + 2 P_{2k}.
    """
    if m == 1:
        return 0, 0
    if n == 0:
        return 0 % m, 1 % m
    p, q = pell_pair_mod(n // 2, m)
    p2 = (2 * p * q) % m
    q2 = (q * q + 2 * p * p) % m
    if n % 2 == 0:
        return p2, q2
    return (p2 + q2) % m, (q2 + 2 * p2) % m


def pell_P_mod(n: int, m: int) -> int:
    """P_n mod m."""
    return pell_pair_mod(n, m)[0]


def divisors(n: int) -> List[int]:
    """All positive divisors of n, ascending."""
    small: List[int] = []
    large: List[int] = []
    d = 1
    while d * d <= n:
        if n % d == 0:
            small.append(d)
            if d != n // d:
                large.append(n // d)
        d += 1
    return small + large[::-1]


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True


def factorize(n: int) -> Dict[int, int]:
    """Trial-division factorisation; adequate for the ranges used here."""
    out: Dict[int, int] = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out


def legendre_two(p: int) -> int:
    """(2/p) for an odd prime p: +1 iff p = +-1 mod 8."""
    return 1 if p % 8 in (1, 7) else -1


def rank_prime(p: int) -> int:
    """alpha(p) for a prime p, using alpha(p) | p - (2/p)."""
    if p == 2:
        return 2
    target = p - legendre_two(p)
    for d in divisors(target):
        if pell_P_mod(d, p) == 0:
            return d
    raise RuntimeError(f"Fermat law violated at p={p} (impossible)")


def rank_prime_power(p: int, k: int) -> int:
    """alpha(p^k) by lifting: alpha(p^{j+1}) is alpha(p^j) or p*alpha(p^j)."""
    r = rank_prime(p)
    mod = p
    for _ in range(1, k):
        mod *= p
        if pell_P_mod(r, mod) != 0:
            r *= p
    return r


def pell_rank(m: int) -> int:
    """alpha(m) for any m >= 1, via multiplicativity on prime powers."""
    if m < 1:
        raise ValueError("modulus must be positive")
    if m == 1:
        return 1
    r = 1
    for p, k in factorize(m).items():
        r = lcm(r, rank_prime_power(p, k))
    return r


def rank_brute(m: int) -> int:
    """Reference implementation: iterate the recursion modulo m."""
    a, b = 0, 1 % m
    for n in range(1, m * m + 2):
        a, b = b, (2 * b + a) % m
        if a == 0:
            return n
    raise RuntimeError("unreachable")


if __name__ == "__main__":
    for m in range(1, 61):
        fast, slow = pell_rank(m), rank_brute(m)
        assert fast == slow, (m, fast, slow)
    print("fast and brute-force ranks agree for 1 <= m <= 60")
    print("alpha(13) =", pell_rank(13), " alpha(169) =", pell_rank(169))
    print("alpha(31) =", pell_rank(31), " alpha(961) =", pell_rank(961))
    print("alpha(10^6 + 3) =", pell_rank(1000003))

"""
Search for Pell-Wall-Sun-Sun primes.

A prime p is a Pell-Wall-Sun-Sun prime if p^2 divides P_{alpha(p)}, where
alpha(p) is the rank of apparition of p on the Pell spine.  Equivalently
alpha(p^2) = alpha(p) rather than the generic p * alpha(p).

For an odd prime p the Fermat law alpha(p) | p - (2/p) restricts the rank to
divisors of p -+ 1, so each prime costs O(d(p -+ 1) * log p) multiplications;
the whole search to X costs about X log X / log log X word operations plus the
sieve.  The known members below 10^6 are 13 and 31.
"""

from __future__ import annotations

from math import lcm
from typing import Iterator, List, Tuple


def pell_pair_mod(n: int, m: int) -> Tuple[int, int]:
    """(P_n mod m, Q_n mod m) by binary doubling; O(log n) multiplications."""
    if m == 1:
        return 0, 0
    if n == 0:
        return 0 % m, 1 % m
    p, q = pell_pair_mod(n // 2, m)
    p2 = (2 * p * q) % m
    q2 = (q * q + 2 * p * p) % m
    if n % 2 == 0:
        return p2, q2
    return (p2 + q2) % m, (q2 + 2 * p2) % m


def sieve(limit: int) -> List[int]:
    """All primes <= limit by the sieve of Eratosthenes."""
    flags = bytearray([1]) * (limit + 1)
    flags[0:2] = b"\x00\x00"
    i = 2
    while i * i <= limit:
        if flags[i]:
            flags[i * i:: i] = bytearray(len(flags[i * i:: i]))
        i += 1
    return [i for i in range(limit + 1) if flags[i]]


def divisors(n: int) -> List[int]:
    small: List[int] = []
    large: List[int] = []
    d = 1
    while d * d <= n:
        if n % d == 0:
            small.append(d)
            if d != n // d:
                large.append(n // d)
        d += 1
    return small + large[::-1]


def legendre_two(p: int) -> int:
    return 1 if p % 8 in (1, 7) else -1


def rank_prime(p: int) -> int:
    """alpha(p), searching only the divisors of p - (2/p)."""
    if p == 2:
        return 2
    for d in divisors(p - legendre_two(p)):
        if pell_pair_mod(d, p)[0] == 0:
            return d
    raise RuntimeError(f"Fermat law violated at p={p} (impossible)")


def wall_sun_sun_primes(limit: int) -> Iterator[Tuple[int, int, int]]:
    """Yield (p, alpha(p), P_alpha(p) mod p^2) for each hit p <= limit."""
    for p in sieve(limit):
        if p == 2:
            continue
        r = rank_prime(p)
        if pell_pair_mod(r, p * p)[0] == 0:
            yield p, r, 0


def growth_ratio_census(limit: int) -> Tuple[int, int]:
    """Count how many primes p <= limit satisfy alpha(p^2) = p*alpha(p) vs not."""
    generic = 0
    exceptional = 0
    for p in sieve(limit):
        if p == 2:
            continue
        r = rank_prime(p)
        if pell_pair_mod(r, p * p)[0] == 0:
            exceptional += 1
        else:
            generic += 1
    return generic, exceptional


if __name__ == "__main__":
    LIMIT = 20000
    hits = list(wall_sun_sun_primes(LIMIT))
    print(f"Pell-Wall-Sun-Sun primes below {LIMIT}:")
    for p, r, _ in hits:
        print(f"   p = {p:>6}   alpha(p) = alpha(p^2) = {r}")
    g, e = growth_ratio_census(LIMIT)
    print(f"generic primes (alpha(p^2) = p*alpha(p)): {g}")
    print(f"exceptional primes:                       {e}")
    print("note: the rank is multiplicative on coprime moduli, e.g.")
    print("   alpha(13*31) =", lcm(rank_prime(13), rank_prime(31)),
          "= lcm(alpha 13, alpha 31)")
